class ScannerStation extends Thread{private final int scripts;ScannerStation(String name,int n){super(name);scripts=n;}public void run(){try{for(int i=1;i<=scripts;i++)Thread.sleep(20);}catch(InterruptedException e){Thread.currentThread().interrupt();}System.out.println(getName()+" scanned "+scripts);}}public class ScannerStations{public static void main(String[]x)throws InterruptedException{Thread[]t=new Thread[4];for(int i=0;i<4;i++){t[i]=new ScannerStation("Station-"+(i+1),10);t[i].start();}int total=0;for(Thread s:t){s.join();if(!s.isAlive())total+=10;}System.out.println("Total scanned: "+total);}}